// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address owner;

    function setUp() public {
        c = new RoundFactory();
        owner = address(0xA11CE);
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.prank(owner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == (newOwner != address(0)), "transfer to zero must revert");
    }
}
